      this.pendingApproval = { id, settle };
      this.emit({
        type: "approval.request",
        id,
        turn_id: turnId,
        tool,
        subject: toolSubject(args),
        preview: redactedJson(args),
        review: approvalReview(tool, args, this.app.getConfig().workspace),
      });
    });
  }

